const date=()=>new Date().toISOString().slice(0,10),keyFor=m=>m==='daily'?'daily:'+date():m,game=()=>view==='result'&&historicalRound?historicalRound:state.games[keyFor(mode)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>n===null?'–':n.toLocaleString('de-DE',{maximumFractionDigits:1,minimumFractionDigits:1}),maxTries=g=>g.length<6?6:7;
