function confirmBox(title,text,action,label='Bestätigen'){if(modal.open)return;document.querySelector('#modal-content').innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><button class="primary" id="confirm-action">${esc(label)}</button><button id="cancel-action">Abbrechen</button>`;modal.showModal();document.querySelector('#confirm-action').onclick=()=>{modal.close();action();};document.querySelector('#cancel-action').onclick=()=>modal.close();}
