function beep(win=false){if(!state.settings.sound)return;try{const C=window.AudioContext||window.webkitAudioContext,c=new C();c.resume();[win?523:320,win?659:440,win?784:380].forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,c.currentTime+i*.09);g.gain.linearRampToValueAtTime(.04,c.currentTime+i*.09+.01);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+i*.09+.14);o.connect(g);g.connect(c.destination);o.start(c.currentTime+i*.09);o.stop(c.currentTime+i*.09+.15);});setTimeout(()=>c.close(),700);}catch{}}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
