function record(g,win,abandoned=false){if(state.events.some(e=>e.id===g.id))return;g.status=win?'won':'lost';g.input='';state.events.push({id:g.id,mode:g.mode,length:g.length,guesses:g.guesses.length,win,abandoned,date:g.mode==='daily'?g.date:date(),wordVersion:g.wordVersion||'de-1'});state.roundResults=state.roundResults||{};state.roundResults[g.id]=JSON.parse(JSON.stringify(g));if(g.mode==='daily')state.daily[g.date]=g.id;if(g.mode==='streak'){state.streak.current=win?state.streak.current+1:0;state.streak.best=Math.max(state.streak.best,state.streak.current);}save();}
function next(){if(historicalRound){historicalRound=null;start(mode);return;}historicalRound=null;resultIndex=0;if(locked)return;if(mode==='survivor')return launchSurvivor();if(mode==='duel')return openDuel();if(mode==='theme'){const s=themeGame();themeCategory=s.categoryId;themeLength=s.rounds[0].length;return launchTheme();}if(mode==='speedrun')return openSpeed();if(mode==='tower')return openTower();if(mode==='double')return startDouble(true);if(mode==='daily'){view='home';render();return;}createRound(mode,mode==='classic'?length:4+Math.floor(Math.random()*4));view='game';render();}
