function render(){if(view==='online')return;renderScreen();if(view==='stats'){const rows=[...Object.values(state.games).filter(g=>g.status!=='playing'&&!state.roundResults?.[g.id]),...Object.values(state.roundResults||{}),...Object.values(state.sessions).filter(s=>s.status!=='playing')].filter(s=>filterMode==='all'||s.mode===filterMode).filter(s=>filterMode!=='double'||filterDoubleLength==='all'||s.rounds[0].length===Number(filterDoubleLength)).sort((a,b)=>b.started-a.started).slice(0,20);if(rows.length)app.innerHTML+='<section class="panel"><h3>Gespeicherte Ergebnisse</h3>'+rows.map(s=>'<button class="secondary" data-action="result-history" data-id="'+esc(s.id)+'">'+esc(WordleResults.model(s).title)+' · '+(s.status==='won'?'Gelöst':'Abgeschlossen')+'</button>').join('')+'</section>';}if(view==='result'&&reportWords().length){const m=WordleResults.model(resultSource(),state);resultIndex=Math.min(resultIndex,m.boards.length-1);const panel=WordleResults.html(m,resultIndex);app.innerHTML=app.innerHTML.replace('<button class="primary wide" data-action="next">',panel+'<button class="primary wide" data-action="next">');app.innerHTML+='<button class="wide quiet" data-action="report-word">⚑ Wortqualität melden</button>';}}
