 if(view.startsWith('duel-')){app.classList.toggle('double-wide',false);if(view==='duel-hub')app.innerHTML=JU.hub(state);else if(view==='duel-random')app.innerHTML=JU.random(duelLength);else if(view==='duel-wish')app.innerHTML=JU.wish();else if(view==='duel-invite'){try{app.innerHTML=JU.invitation(pendingDuel(),state,duelCreated);}catch{app.innerHTML=JU.invalid();}}else app.innerHTML=JU.invalid();return;}
