app.addEventListener('pointerup',e=>{if(!swipeStart)return;const deltaX=e.clientX-swipeStart.x,deltaY=e.clientY-swipeStart.y;swipeStart=null;if(locked||mode!=='double'||view!=='game')return;if(Math.abs(deltaX)>45&&Math.abs(deltaX)>Math.abs(deltaY)*1.5){const s=doubleGame();selectDouble(s.rounds.find(r=>r.id!==U.active(s)).id);}});
