// Tower uses the same state, word bags, animations and share/persistence services.
function towerGame(){return state.sessions[towerId];}
function runningTower(){return Object.values(state.sessions).find(s=>s.mode==='tower'&&s.status==='playing');}
function openTower(){if(locked||modal.open)return;mode='tower';view='tower-start';render();}
function launchTower(){
 if(locked||modal.open)return;
 let s=runningTower();if(!s){const id=globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;s=T.create({id,targets:[4,5,6,7].map(n=>draw(n,'tower')),started:Date.now()},W);state.sessions[id]=s;save();}
 towerId=s.id;mode='tower';view='game';render();
}
function followTowerRow(){
 const area=app.querySelector('.tower-history'),row=app.querySelector('[data-current-row]');
 if(!area||!row?.getBoundingClientRect)return;
 const a=area.getBoundingClientRect(),r=row.getBoundingClientRect();
 if(r.bottom>a.bottom-8)area.scrollTop+=r.bottom-a.bottom+8;
 else if(r.top<a.top+4)area.scrollTop-=a.top-r.top+4;
}
function renderTowerGame(index){app.innerHTML=TU.game(towerGame(),index);followTowerRow();}
function advanceTower(){const s=towerGame();if(locked||!s||s.status!=='playing'||!s.pendingTransition)return;storeSession(T.advance(s,W));view='game';render();}
function towerInvalid(message){toast(message);const r=app.querySelector('[data-current-row]');r?.classList.add('shake');setTimeout(()=>r?.classList.remove('shake'),300);}
function towerInput(k){
 const s=towerGame();if(!s||s.status!=='playing'||s.pendingTransition){render();return;}
 const p=T.progress(s),n=p.active.length;
 if(k==='Enter'){
  const err=T.error(s,s.input||'',W);if(err)return towerInvalid(err);
  locked=true;const next=T.submit(s,s.input,Date.now(),W),solved=next.attempts.at(-1).word===p.active.target;
  storeSession(next);renderTowerGame(p.index);
  const row=app.querySelector(`[data-tower-row="${p.active.guesses.length}"]`);row?.querySelectorAll('.tile').forEach(tile=>tile.classList.add('flip'));
  beep(solved);clearTimeout(roundTimer);roundTimer=setTimeout(()=>{if(solved)row?.classList.add('win');roundTimer=setTimeout(()=>{locked=false;render();},solved&&!reduced()?350:60);},reduced()?40:350+n*45);return;
 }
 if(k==='Backspace')s.input=E.letters(s.input||'').slice(0,-1).join('');
 else{const c=E.normalize(k);if(!/^[A-ZÄÖÜẞ]$/.test(c)||E.letters(s.input||'').length>=n)return;s.input=(s.input||'')+c;}
 save();renderTowerGame();
}
function towerMenu(){
 const s=towerGame();if(locked||modal.open||!s||s.status!=='playing')return;
 document.querySelector('#modal-content').innerHTML='<h2>Aufstieg pausieren?</h2><p>Etage, Hinweise, Übergang und Restbudget bleiben gespeichert. Ein bestätigter Abbruch zählt als verlorener Tower.</p><button class="primary" id="continue">Weiterspielen</button><button id="pause">Pausieren & Hauptmenü</button><button class="danger" id="abandon">Tower abbrechen</button>';
 modal.showModal();document.querySelector('#continue').onclick=()=>modal.close();document.querySelector('#pause').onclick=()=>{modal.close();view='home';render();};document.querySelector('#abandon').onclick=()=>{modal.close();confirmBox('Tower abbrechen?','Dies zählt einmal als Niederlage. Deine erreichte Etage und abgeschlossene Wörter bleiben in der Tower-Statistik erhalten.',()=>{const current=towerGame();if(current?.status==='playing'){storeSession(T.abandon(current,Date.now(),W));view='result';render();}},'Tower abbrechen');};
}
/* Phase 4 controller: monotone foreground time, durable resume checkpoints. */
function followSpeedRow(){
 const area=app.querySelector('.speed-board-wrap'),row=app.querySelector('[data-speed-current]');if(!area||!row?.getBoundingClientRect)return;const a=area.getBoundingClientRect(),r=row.getBoundingClientRect();if(r.bottom>a.bottom-4)area.scrollTop+=r.bottom-a.bottom+4;else if(r.top<a.top+4)area.scrollTop-=a.top-r.top+4;
}
function speedGame(){return state.sessions[speedId];}
function runningSpeed(){return Object.values(state.sessions).find(s=>s.mode==='speedrun'&&s.speedrunVersion===1&&s.status==='playing');}
function speedChoice(){const length=R.chooseLength();return {length,target:draw(length,'speedrun')};}
function openSpeed(){if(locked||modal.open)return;mode='speedrun';view='speed-start';render();}
function launchSpeed(){
 if(locked||modal.open)return;
 let s=runningSpeed();if(!s){const choice=speedChoice();s=R.create({id:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`,started:Date.now(),...choice},W);storeSession(s);}
 speedId=s.id;speedFeedback='';mode='speedrun';resumeSpeed();
}
function resumeSpeed(){const s=speedGame();if(!s||s.status!=='playing'||document.visibilityState==='hidden'||modal.open)return;speedClock.stop();speedClock.resume(s);lastSpeedCheckpoint=performance.now();view='game';render();}
function endSpeed(ms){const s=speedGame();if(!s||s.status!=='playing')return;speedClock.stop();clearTimeout(roundTimer);locked=false;storeSession(R.expire(s,ms,Date.now(),W));view='result';render();}
function checkpointSpeed(){
 const s=speedGame();if(!s||!speedClock.running)return s;
 const next=speedClock.checkpoint(s);if(R.remaining(next)===0){endSpeed(next.activeMs);return null;}
 state.sessions[s.id]=next;lastSpeedCheckpoint=performance.now();save();return next;
}
function pauseSpeed(show=true){
 const s=speedGame();if(!s||s.status!=='playing')return;
 if(speedClock.running){const next=speedClock.pause(s);if(R.remaining(next)===0){endSpeed(next.activeMs);return;}state.sessions[s.id]=next;save();}
 clearTimeout(roundTimer);locked=false;if(show){view='speed-paused';render();}
}
function paintSpeedTime(){
 const s=speedGame();if(!s||!speedClock.running)return;
 if(document.visibilityState==='hidden'||view!=='game'||mode!=='speedrun'){pauseSpeed();return;}
 const ms=speedClock.elapsed(s),left=R.remaining(s,ms);if(left===0){endSpeed(ms);return;}
 const timer=app.querySelector('#speed-time'),bar=app.querySelector('#speed-progress'),box=app.querySelector('.speed-timer');
 if(timer)timer.textContent=RU.time(left);if(bar)bar.style.width=left/R.BUDGET*100+'%';box?.classList.toggle('warning',left<30000&&left>=10000);box?.classList.toggle('urgent',left<10000);
 if(performance.now()-lastSpeedCheckpoint>=500)checkpointSpeed();
}
function speedInvalid(msg){speedFeedback=msg;const feedback=app.querySelector('#speed-feedback');if(feedback)feedback.textContent=msg;const s=speedGame();const row=app.querySelector(`[data-speed-row="${R.active(s).guesses.length}"]`);row?.classList.add('shake');setTimeout(()=>row?.classList.remove('shake'),160);}
function speedInput(k){
 if(!speedClock.running)return;if(document.visibilityState==='hidden'){pauseSpeed();return;}
 // Capture and commit time BEFORE processing a guess or starting an animation.
 const s=checkpointSpeed();if(!s)return;
 const r=R.active(s);
 if(k==='Enter'){
  const err=R.error(s,s.input,W);if(err)return speedInvalid(err);
  locked=true;const old=r.id,next=R.submit(s,s.input,s.activeMs,Date.now(),W,speedChoice);
  storeSession(next);const changed=R.active(next).id!==old;
  if(changed){const end=next.roundEnds.at(-1);speedFeedback=end.reason==='won'?`+${R.POINTS[r.length]} Punkte · ${r.target} gelöst!`:`Das Wort war ${r.target} · weiter geht’s!`;beep(end.reason==='won');}
  // Show the evaluated row briefly, then the already persisted next word.
  app.innerHTML=RU.game(next,R.remaining(next,speedClock.elapsed(next)),changed?Sessions.roundView(next,old):undefined,speedFeedback);followSpeedRow();
  app.querySelector(`[data-speed-row="${r.guesses.length}"]`)?.querySelectorAll('.tile').forEach(t=>t.classList.add('flip'));
  clearTimeout(roundTimer);roundTimer=setTimeout(()=>{locked=false;render();},reduced()?30:200);return;
 }
 if(k==='Backspace')s.input=E.letters(s.input).slice(0,-1).join('');
 else{const c=E.normalize(k);if(!/^[A-ZÄÖÜẞ]$/.test(c)||E.letters(s.input).length>=r.length)return;s.input+=c;}
 save();app.innerHTML=RU.game(s,R.remaining(s,speedClock.elapsed(s)),undefined,speedFeedback);followSpeedRow();
}
function skipSpeed(){
 if(locked||!speedClock.running||modal.open)return;if(document.visibilityState==='hidden'){pauseSpeed();return;}
 const s=checkpointSpeed();if(!s)return;locked=true;
 const next=R.skip(s,s.activeMs,Date.now(),W,speedChoice);storeSession(next);
 if(next.status!=='playing'){speedClock.stop();locked=false;view='result';render();return;}
 speedFeedback='Übersprungen · −10 Sekunden';render();clearTimeout(roundTimer);roundTimer=setTimeout(()=>{locked=false;},180);
}
function abandonSpeed(){
 pauseSpeed();const s=speedGame();if(!s||s.status!=='playing')return;
 confirmBox('Speedrun abbrechen?','Der Run wird einmal als Abbruch erfasst. Tatsächlich erspielte Punkte bleiben erhalten.',()=>{const current=speedGame();if(current?.status==='playing'){speedClock.stop();storeSession(R.abandon(current,current.activeMs,Date.now(),W));view='result';render();}},'Run abbrechen');
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&speedClock.running)pauseSpeed();});
window.addEventListener('pagehide',()=>{if(speedClock.running)pauseSpeed();});
setInterval(paintSpeedTime,100);

