function themeGame(){return state.sessions[themeId];}
function runningTheme(){return Object.values(state.sessions).find(s=>s.mode==='theme'&&s.themeContract===1&&s.status==='playing');}
function openTheme(){if(locked||modal.open)return;mode='theme';view='theme-start';render();}
