function themeMenu(){const s=themeGame();if(locked||modal.open||!s||s.status!=='playing')return;document.querySelector('#modal-content').innerHTML='<h2>Eine kleine Pause?</h2><p>Kategorie, Lösung und Eingabe bleiben gespeichert. Ein bestätigter Abbruch zählt als verlorene Themenrunde.</p><button class="primary" id="continue">Weiterspielen</button><button id="pause">Pausieren & Hauptmenü</button><button class="danger" id="abandon">Themenrunde abbrechen</button>';modal.showModal();document.querySelector('#continue').onclick=()=>modal.close();document.querySelector('#pause').onclick=()=>{modal.close();view='home';render();};document.querySelector('#abandon').onclick=()=>{modal.close();confirmBox('Themenrunde abbrechen?','Die Runde zählt einmal als Niederlage. Andere Modi bleiben erhalten.',()=>{const current=themeGame();if(current?.status==='playing'){storeSession(H.abandon(current,Date.now(),W));view='result';render();}},'Runde abbrechen');};}

/* Phase 6: invitations never start a session until accepted. */
function duelGame(){return state.sessions[duelId];}
function openDuel(){mode='duel';view='duel-hub';duelComparison=null;render();}
function pendingDuel(){return duelChallenge|| (duelGame()?J.challenge(duelGame()):null);}
function showDuel(c,created=false){onlineController?.dispose();onlineController=null;try{J.resolve(state,c,W);duelChallenge=c;duelCreated=created;duelComparison=null;mode='duel';view='duel-invite';render();}catch{mode='duel';view='duel-invalid';render();}}
