function createDuel(type){if(modal.open||locked||view!==(type==='wish'?'duel-wish':'duel-random'))return;try{const raw=type==='wish'?document.querySelector('#duel-word').value:draw(duelLength,'duel');if(type==='wish'){const err=L.wordError(raw,W);if(err){document.querySelector('#duel-word-error').textContent=err;toast(err);return;}}
 const c=L.create(type,raw,W);state=J.register(state,c,W);save();showDuel(c,true);
 }catch(error){toast(error.message);}}
function acceptDuel(){try{const c=pendingDuel();if(!c)return;state=J.accept(state,c,Date.now(),W);duelId=J.sessionId(c.id);save();view=duelGame().status==='playing'?'game':'result';mode='duel';duelComparison=null;render();}catch(error){toast(error.message);}}
