function duelInput(k){const s=duelGame();if(!s||s.status!=='playing'){render();return;}const r=Sessions.roundView(s,'word');if(k==='Enter'){const err=J.error(s,s.input,W);if(err){toast(err);const row=app.querySelector(`[data-theme-row="${r.guesses.length}"]`);row?.classList.add('shake');setTimeout(()=>row?.classList.remove('shake'),300);return;}
 locked=true;const next=J.submit(s,s.input,Date.now(),W);storeSession(next);renderDuelGame();const row=app.querySelector(`[data-theme-row="${r.guesses.length}"]`);row?.querySelectorAll('.tile').forEach(t=>t.classList.add('flip'));beep(next.status==='won');clearTimeout(roundTimer);roundTimer=setTimeout(()=>{locked=false;view=next.status==='playing'?'game':'result';render();},reduced()?40:350+r.length*45);return;}
 if(k==='Backspace')s.input=E.letters(s.input).slice(0,-1).join('');else{const c=E.normalize(k);if(!/^[A-ZÄÖÜẞ]$/.test(c)||E.letters(s.input).length>=r.length)return;s.input+=c;}save();renderDuelGame();}
