async function duelLinkShare(copy=false){const c=pendingDuel();if(!c)return;try{J.resolve(state,c,W);if(!/^https?:$/.test(location.protocol))return info('Öffentlicher Link benötigt','Lokale Datei-Links sind für Freunde nicht erreichbar. Öffne diese Spielversion auf einem isolierten HTTPS-Testserver oder nach der gemeinsamen Veröffentlichung.');const url=L.link(c,location.href,W),text=c.type==='random'?`⚔️ Ich fordere dich bei WORDLE DE heraus!\nWir bekommen dasselbe deutsche Wort. Wer benötigt weniger Versuche?\nHier spielen: ${url}`:`⚔️ Ich habe ein deutsches Worträtsel für dich bei WORDLE DE!\nKannst du es knacken?\nHier spielen: ${url}`;
 if(copy){try{if(!navigator.clipboard||!isSecureContext)throw Error();await navigator.clipboard.writeText(url);toast('Link kopiert.');return;}catch{manualShare(url);return;}}return shareText(text);
 }catch(error){toast(error.message);}}
